}
{
$ U_{ABL} = U_q \cdot \frac{R || R_L}{2R + R || R_L}$
}

\begin{align*}
\frac{U_{ABL}-U_{AB}}{U_{AB}} &= -10\% = -0,1

\frac{U_{ABL}}{U_{AB}}-1 &= -0,1

\frac{U_{ABL}}{U_{AB}} &= 0,9
\end{align*}

\begin{align*}
\frac{U_{ABL}}{U_q}= \frac{U_{ABL}}{3 U_{AB}} &= \frac{R||R_L}{2R+R||R_L} = \frac{1}{1+\frac{2R}{R||R_L}}

0,3 &= \frac{1}{1+ 2R \left(\frac{1}{R}+ \frac{1}{R_L} \right)}=\frac{1}{3+2\frac{R}{R_L}}

\frac{1}{0,3} &= 3 + 2\frac{R}{R_L}

\frac{1}{3}&= 2\frac{R}{R_L}

R_L &= 6R = 60\mathrm{k}\Omega
\end{align*}

