\begin{align*}
\frac{U_{ABL}}{U_q}= \frac{U_{ABL}}{3 U_{AB}} &= \frac{\frac{R}{2}||R_L}{R+\frac{R}{2}||R_L} = \frac{1}{1+\frac{R}{\frac{R}{2}||R_L}}

0,3 &= \frac{1}{1+ R \left(\frac{2}{R}+ \frac{1}{R_L} \right)}=\frac{1}{3+\frac{R}{R_L}}

\frac{1}{0,3} &= 3 + \frac{R}{R_L}

\frac{1}{3}&= \frac{R}{R_L}

R_L &= 3R = 30\mathrm{k}\Omega
\end{align*}

